/* Runner entry points */
void func_RESET(void) { uint16_t _saved_wb = g_code_window_base; g_code_window_base = 0xE000; func_FFB0(); g_code_window_base = _saved_wb; }
uint16_t g_rti_target = 0; /* RTI hijack target (set by RTI, consumed by func_NMI) */
uint16_t g_rti_source = 0; /* last generated RTI instruction address */
int g_rti_bank = -1; /* bank for last generated RTI instruction */
uint16_t g_rts_target = 0; /* last RTS operand popped by generated code */

void func_NMI(void)   {
    /* The runner pushes the 6502 NMI hardware frame.
     * Uses $0000 as sentinel PC — RTI stores the target in g_rti_target.
     * If the handler modified the return address (RTI hijack),
     * we dispatch to the hijacked target AFTER the handler returns,
     * so the post-NMI code runs outside the NMI context (depth 0). */
    g_rti_target = 0;
    uint16_t _nmi_saved_wb = g_code_window_base;
    g_code_window_base = 0xC000;
    func_C0D9();
    g_code_window_base = _nmi_saved_wb;
    if (g_rti_target != 0) {
        /* Post-NMI code runs outside NMI context on real hardware
         * (RTI re-enables interrupts, NMI is edge-triggered).
         * Clear pending VBlank to prevent re-entrant NMI during
         * the post-NMI path - real hardware only fires NMI once
         * per VBlank transition. */
        runtime_begin_post_nmi();
        call_by_address(g_rti_target);
        runtime_end_post_nmi();
    }
}
void func_IRQ(void)   { uint16_t _saved_wb = g_code_window_base; g_code_window_base = 0xE000; func_FFB0(); g_code_window_base = _saved_wb; }
